# 2) background.js (the brain)

Paste your **free Hugging Face token** in `HF_TOKEN`.

```js
// background.js

// =========================
// CONFIG
// =========================
const HF_TOKEN = "hf_XXXXXXXXXXXXXXXXXXXXXXXXXXXX"; // <- put your free HF token here
const HF_MODEL = "Salesforce/codet5-base"; // good default for code feedback
const HF_URL = `https://api-inference.huggingface.co/models/${HF_MODEL}`;

const API_INTERVAL_MS = 5000; // throttle: 1 call / 5s (tune as needed)
let lastApiCall = 0;

const DEFAULT_SETTINGS = {
  autoAnalyze: true,
  mode: "hybrid" // 'hybrid' (API + fallback) | 'offline' (fallback only)
};

// =========================
// MESSAGE HANDLER
// =========================
chrome.runtime.onMessage.addListener(async (msg, sender) => {
  if (msg?.action !== "analyze_code") return;

  try {
    const settings = await getSyncSettings(DEFAULT_SETTINGS);
    if (!settings.autoAnalyze) {
      // user turned off auto analysis; do nothing
      return;
    }

    const code = String(msg.code || "");
    const codeHash = await sha256hex(code);

    // cache check
    const cached = await storageGetLocal(codeHash);
    if (cached) {
      respond(sender.tab.id, msg.id, cached);
      return;
    }

    // choose mode
    let feedback;
    if (settings.mode === "offline") {
      feedback = runOfflineLint(code);
    } else {
      // hybrid: try API, fallback to offline
      feedback = await tryApiThenFallback(code);
    }

    // cache & respond
    await storageSetLocal({ [codeHash]: feedback });
    await enforceCacheLimit(200); // keep last 200 entries
    respond(sender.tab.id, msg.id, feedback);
  } catch (err) {
    console.warn("CodeLens background error:", err);
    respond(sender.tab.id, msg.id, "⚠️ Analysis failed. (Background error)");
  }
});

// =========================
// CORE LOGIC
// =========================
async function tryApiThenFallback(code) {
  const apiOk = Boolean(HF_TOKEN && HF_TOKEN.startsWith("hf_"));
  if (!apiOk) return runOfflineLint(code);

  try {
    await throttle();
    const raw = await callHuggingFace(code);
    const formatted = formatFeedback(raw);
    return formatted || runOfflineLint(code);
  } catch (e) {
    console.warn("HF API failed, using offline lint:", e?.message || e);
    return runOfflineLint(code);
  }
}

async function callHuggingFace(code) {
  const prompt = [
    "You are a senior software engineer.",
    "Review the following code. In 3-6 concise bullet points:",
    "- call out logic issues or edge cases",
    "- suggest performance improvements",
    "- note readability or style concerns",
    "- (if possible) hint at Big-O complexity",
    "",
    "Code:",
    "```",
    code,
    "```"
  ].join("\n");

  const res = await fetch(HF_URL, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${HF_TOKEN}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ inputs: prompt })
  });

  if (!res.ok) {
    throw new Error(`HF ${res.status}`);
  }
  const data = await res.json();
  // Many HF text models return [{generated_text: "..."}]
  const text = Array.isArray(data) ? data[0]?.generated_text : data?.generated_text;
  return typeof text === "string" ? text : JSON.stringify(data);
}

function formatFeedback(raw) {
  if (!raw) return "";
  // Normalize: split into lines and bullet them
  const lines = raw
    .split(/\r?\n|•|-/)
    .map(s => s.trim())
    .filter(Boolean)
    .slice(0, 8); // cap to keep it tight

  const bullets = lines.map(l => `• ${l}`);
  // Deduplicate common noise
  return [...new Set(bullets)].join("\n");
}

function runOfflineLint(code) {
  const fb = [];

  // Extremely common JS pitfalls / generic hints:
  if (/\b==\b/.test(code) && !/\b===\b/.test(code)) {
    fb.push("Use strict equality '===' instead of '==' to avoid type coercion pitfalls.");
  }
  if (/for\s*\(.+;.+;.+\)\s*\{[\s\S]*for\s*\(.+\)\s*\{/.test(code)) {
    fb.push("Nested loops detected — consider refactoring to reduce O(n²) where possible.");
  }
  if (/while\s*\(\s*true\s*\)/i.test(code)) {
    fb.push("Possible infinite loop — ensure a termination condition.");
  }
  if (/var\s+/.test(code)) {
    fb.push("Prefer 'let'/'const' over 'var' for block scoping and clarity.");
  }
  if (code.length > 1200) {
    fb.push("Very long snippet — consider modularizing into smaller functions.");
  }
  if (!/(function|class)\s+/.test(code) && code.split("\n").length > 25) {
    fb.push("Consider introducing functions/classes for structure and reusability.");
  }
  if (/\bconsole\.log\(/.test(code)) {
    fb.push("Remove debug logs or guard them behind environment checks.");
  }
  if (/catch\s*\(\s*\w*\s*\)\s*\{\s*\}/.test(code)) {
    fb.push("Empty catch block — at least log or handle the error.");
  }

  if (fb.length === 0) return "✅ No obvious issues found by offline checks.";
  return fb.map(s => `• ${s}`).join("\n");
}

// =========================
// UTILITIES
// =========================
function respond(tabId, id, feedback) {
  chrome.tabs.sendMessage(tabId, {
    action: "inject_feedback",
    id,
    feedback
  });
}

async function throttle() {
  const now = Date.now();
  const delta = now - lastApiCall;
  if (delta < API_INTERVAL_MS) {
    await sleep(API_INTERVAL_MS - delta);
  }
  lastApiCall = Date.now();
}

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

async function sha256hex(text) {
  const enc = new TextEncoder();
  const data = enc.encode(text);
  const hash = await crypto.subtle.digest("SHA-256", data);
  return [...new Uint8Array(hash)].map(b => b.toString(16).padStart(2, "0")).join("");
}

// storage helpers
function storageGetLocal(key) {
  return new Promise(resolve => {
    if (!key) resolve(undefined);
    chrome.storage.local.get(key, (data) => resolve(data?.[key]));
  });
}
function storageSetLocal(obj) {
  return new Promise(resolve => chrome.storage.local.set(obj, resolve));
}
function storageGetAllLocal() {
  return new Promise(resolve => chrome.storage.local.get(null, resolve));
}
async function enforceCacheLimit(limit = 200) {
  const all = await storageGetAllLocal();
  const keys = Object.keys(all || {});
  if (keys.length <= limit) return;
  // nuke old cache — simplest strategy
  await new Promise(r => chrome.storage.local.clear(r));
}

// settings
function getSyncSettings(defaults) {
  return new Promise(resolve => {
    chrome.storage.sync.get(defaults, resolve);
  });
}
