# 3) content.js (the eyes + hands)

- Scans the page for `<pre>`/`<code>` blocks
- Uses a **MutationObserver** to catch dynamically loaded code (e.g., GitHub)
- Sends snippets for analysis
- Injects the 💡 badge and the sliding sidebar

```js
// content.js

const MIN_CHARS = 40;      // ignore tiny inline code
const SCAN_INTERVAL = 0;   // we rely on observer; interval not needed by default

const seenIds = new Set();

function scanAndSend() {
  const blocks = document.querySelectorAll("pre, code");
  let index = 0;

  blocks.forEach((block) => {
    if (!block) return;
    if (block.dataset.codelensId) return; // already tagged

    const code = (block.innerText || "").trim();
    if (!code || code.length < MIN_CHARS) return;
    if (!looksLikeCode(code)) return;

    block.dataset.codelensId = (++index) + ":" + Math.random().toString(36).slice(2);
    const id = block.dataset.codelensId;

    if (seenIds.has(id)) return;
    seenIds.add(id);

    chrome.runtime.sendMessage({
      action: "analyze_code",
      id,
      code
    });
  });
}

// basic "looks like code" heuristic
function looksLikeCode(text) {
  const lines = text.split("\n");
  let score = 0;
  if (/[{};()=]/.test(text)) score++;
  if (/function|class|const|let|var|def|#include|public|private/.test(text)) score++;
  if (lines.length >= 3) score++;
  return score >= 2;
}

// receive feedback
chrome.runtime.onMessage.addListener((msg) => {
  if (msg?.action !== "inject_feedback") return;
  injectBadgeAndHook(msg.id, msg.feedback);
});

function injectBadgeAndHook(id, feedback) {
  const block = document.querySelector(`[data-codelens-id="${CSS.escape(id)}"]`);
  if (!block) return;

  // badge
  const badge = document.createElement("span");
  badge.className = "codelens-badge";
  badge.textContent = "💡 Insights";
  badge.title = "View CodeLens review";
  badge.addEventListener("click", () => openSidebar(feedback));

  // insert right after the block
  const parent = block.parentNode;
  if (!parent) return;
  // avoid duplicate badges
  if (parent.querySelector(`.codelens-badge[data-for="${CSS.escape(id)}"]`)) return;
  badge.setAttribute("data-for", id);

  // a tiny spacer wrapper prevents layout jumps
  const wrapper = document.createElement("div");
  wrapper.className = "codelens-badge-wrapper";
  wrapper.appendChild(badge);

  parent.insertBefore(wrapper, block.nextSibling);
}

// Sidebar
function openSidebar(feedback) {
  let panel = document.getElementById("codelens-panel");
  if (!panel) {
    panel = document.createElement("div");
    panel.id = "codelens-panel";
    panel.innerHTML = `
      <div id="codelens-header">
        <div>🧠 CodeLens Review</div>
        <div class="codelens-header-actions">
          <button id="codelens-copy" title="Copy feedback">Copy</button>
          <button id="codelens-close" title="Close">×</button>
        </div>
      </div>
      <pre id="codelens-feedback"></pre>
    `;
    document.body.appendChild(panel);

    document.getElementById("codelens-close").onclick = () => panel.remove();
    document.getElementById("codelens-copy").onclick = () => {
      const t = document.getElementById("codelens-feedback").innerText;
      navigator.clipboard.writeText(t).catch(() => {});
    };
  }
  const target = document.getElementById("codelens-feedback");
  target.innerText = feedback || "No feedback.";
}

// Observe dynamic content (GitHub, docs, SPAs)
const observer = new MutationObserver(() => {
  // debounce microtask
  queueMicrotask(scanAndSend);
});

observer.observe(document.documentElement, {
  childList: true,
  subtree: true
});

// initial scan
window.addEventListener("load", () => {
  scanAndSend();
});

// if you really want a periodic backstop scan (optional):
if (SCAN_INTERVAL > 0) {
  setInterval(scanAndSend, SCAN_INTERVAL);
}
```

